sys_script_include.script:
var LabTestSlotCheck = Class.create();
LabTestSlotCheck.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

    slotCheck: function() {
        var dateStr = this.getParameter("sysparm_date");
        var dayStart = new GlideDateTime(dateStr);
        var dayEnd = new GlideDateTime(dateStr);

        dayStart.setDisplayValue(dayStart.getDate() + " 00:00:00");
        dayEnd.setDisplayValue(dayEnd.getDate() + " 23:59:59");

        var gr = new GlideRecord("u_lab_test");
        gr.addQuery("u_scheduled_date", ">=", dayStart);
        gr.addQuery("u_scheduled_date", "<=", dayEnd);
        gr.query();

        if (gr.getRowCount() >= 3) {
            return "false";
        }

        return "true";
    },

    type: 'LabTestSlotCheck'
});
